<script setup>
import {computed,onMounted} from 'vue';
import {useRoute} from 'vue-router';
import Icon from '../components/Icon.vue';
import {state,loadConfig} from '../lib';
const route=useRoute(),contact=computed(()=>route.path==='/kontak');
const safeURL=value=>{try{const url=new URL(value);return url.protocol==='https:'?url.href:null;}catch{return null;}};
const mapURL=computed(()=>{const value=state.config?.map_embed_url;try{const url=new URL(value);return url.protocol==='https:'&&['www.google.com','maps.google.com'].includes(url.hostname)?url.href:null;}catch{return null;}});
onMounted(()=>loadConfig().catch(()=>{}));
</script>
<template><div class="container inner-page information-page"><template v-if="!contact"><span class="large-icon"><Icon name="Leaf" :size="32"/></span><h1 class="page-heading">Ruang kecil untuk<br/>jeda yang berarti.</h1><div class="about-text"><p>Taman Teras Cafe berdiri pada 18 Agustus 2026. Berawal dari banyaknya mahasiswa di sekitar rumah yang mencari tempat makan atau sekadar berkumpul di sela kegiatan kuliah, Taman Teras hadir sebagai tempat untuk singgah.</p><p>Di sini, makanan dan minuman menjadi teman untuk mengisi jeda, berbagi cerita, dan menikmati waktu bersama. Pilih menu melalui ponselmu, lalu nikmati di meja atau bawa pulang.</p><p>Kami melayani pesanan dine-in dan takeaway, Senin hingga Jumat, pukul 08.30–16.00 WIB.</p></div><RouterLink class="button primary" to="/">Lihat menu <Icon name="ArrowRight" :size="18"/></RouterLink></template><template v-else><h1 class="page-heading">Mampir ke Taman Teras.</h1><p class="page-intro">Temukan kami dan rencanakan jedamu.</p><div class="contact-grid"><section class="panel"><h2><Icon name="MapPin"/>Alamat cafe</h2><p>{{state.config?.address||'Alamat lengkap akan diperbarui oleh pengelola cafe.'}}</p><a v-if="safeURL(state.config?.map_url)" class="text-button" :href="safeURL(state.config.map_url)" target="_blank" rel="noopener noreferrer">Buka Google Maps <Icon name="ExternalLink" :size="16"/></a><h2><Icon name="Clock"/>Jam operasional</h2><p>Senin–Jumat<br/><strong>08.30–16.00 WIB</strong></p><p class="muted">Sabtu–Minggu tutup.</p><h2><Icon name="Phone"/>Hubungi kami</h2><a v-if="state.config?.whatsapp" class="button primary" :href="'https://wa.me/'+state.config.whatsapp.replace(/\D/g,'').replace(/^0/,'62')" target="_blank" rel="noopener noreferrer">WhatsApp cafe <Icon name="ArrowUpRight" :size="17"/></a><p v-else class="muted">Nomor WhatsApp cafe belum dicantumkan.</p><a v-if="safeURL(state.config?.instagram_url)" class="text-button" :href="safeURL(state.config.instagram_url)" target="_blank" rel="noopener noreferrer">Instagram <Icon name="ExternalLink" :size="16"/></a></section><div class="map-panel"><iframe v-if="mapURL" :src="mapURL" title="Lokasi Taman Teras Cafe" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><div v-else class="empty-state"><Icon name="MapPin" :size="42"/><h2>Lokasi segera tersedia</h2><p>Peta akan muncul setelah alamat asli cafe dilengkapi.</p></div></div></div></template></div></template>
